package com.streamcraft.core.runtime;
import com.fasterxml.jackson.databind.ObjectMapper; import com.streamcraft.core.model.DataEntity; import com.streamcraft.shared.file.HdfsFileSourceConfig; import java.io.*; import java.nio.charset.*; import java.util.*; import java.util.concurrent.*; import org.apache.flink.api.connector.source.*; import org.apache.flink.core.fs.*; import org.apache.flink.core.io.InputStatus; import org.slf4j.*;
final class HdfsFileSourceReader implements SourceReader<DataEntity,HdfsFileSourceSplit>{private static final Logger LOG=LoggerFactory.getLogger(HdfsFileSourceReader.class);private final SourceReaderContext context;private final HdfsFileSourceConfig config;private final Object lock=new Object();private final ArrayDeque<DataEntity> records=new ArrayDeque<>();private final ObjectMapper mapper=new ObjectMapper();private HdfsFileSourceSplit split;private boolean started,exhausted;private long nextPoll;
 HdfsFileSourceReader(SourceReaderContext c,HdfsFileSourceConfig cfg){context=c;config=cfg;}public void start(){started=true;context.sendSplitRequest();}public InputStatus pollNext(ReaderOutput<DataEntity>out)throws Exception{synchronized(lock){if(!started||split==null)return InputStatus.NOTHING_AVAILABLE;if(!records.isEmpty()){out.collect(records.removeFirst());return records.isEmpty()?InputStatus.NOTHING_AVAILABLE:InputStatus.MORE_AVAILABLE;}if(exhausted)return InputStatus.END_OF_INPUT;if(System.currentTimeMillis()<nextPoll)return InputStatus.NOTHING_AVAILABLE;read();if(!records.isEmpty()){out.collect(records.removeFirst());return records.isEmpty()?InputStatus.NOTHING_AVAILABLE:InputStatus.MORE_AVAILABLE;}if(config.readMode()==HdfsFileSourceConfig.ReadMode.FULL){exhausted=true;return InputStatus.END_OF_INPUT;}nextPoll=System.currentTimeMillis()+config.pollIntervalMillis();return InputStatus.NOTHING_AVAILABLE;}}
 public List<HdfsFileSourceSplit> snapshotState(long id){synchronized(lock){return split==null?List.of():List.of(split);}}public CompletableFuture<Void>isAvailable(){return CompletableFuture.completedFuture(null);}public void addSplits(List<HdfsFileSourceSplit>s){synchronized(lock){if(!s.isEmpty())split=s.get(0);exhausted=false;}}public void notifyNoMoreSplits(){}public void close(){exhausted=true;}
 private void read()throws Exception{HdfsFileSourceSplit cur=split;Path p=new Path(cur.state().path());FileStatus st=p.getFileSystem().getFileStatus(p);String fp=p+":"+st.getLen()+":"+st.getModificationTime();if(!fp.equals(cur.state().fingerprint())){LOG.warn("Skipping changed HDFS file {}",p);return;}try(FSDataInputStream in=p.getFileSystem().open(p)){if(cur.state().byteOffset()>0)in.seek(cur.state().byteOffset());BufferedReader br=new BufferedReader(new InputStreamReader(in,Charset.forName(config.encoding())));long line=cur.state().lineNumber();List<String>names=new ArrayList<>(config.fieldNames());boolean header=cur.state().headerSeen();String text;while((text=br.readLine())!=null){line++;if(text.isBlank())continue;if(line<=config.skipHeaderRowNumber())continue;if(config.fileFormatType()==com.streamcraft.shared.file.HdfsFileFormatType.CSV&&config.csvUseHeaderLine()&&names.isEmpty()){names=HdfsFileRuntimeSupport.parseCsvLine(text,config.fieldDelimiter());header=true;continue;}try{Map<String,Object>f=HdfsFileRuntimeSupport.parseRecord(config.fileFormatType(),text,names,config.fieldDelimiter(),mapper);if(config.parsePartitionFromPath()){Map<String,Object>m=new LinkedHashMap<>(parts(p));m.putAll(f);f=m;}records.add(entity(p,line,f));}catch(Exception e){LOG.warn("Skipping HDFS line {}: {}",line,e.getMessage());}}long offset=st.getLen();split=new HdfsFileSourceSplit(cur.splitId(),new HdfsFileSourceState(p.toString(),fp,offset,line,config.fileFormatType().name(),header,true));}}
 private DataEntity entity(Path p,long line,Map<String,Object>f){Object id=config.idField().isBlank()?null:f.get(config.idField());String sid=id==null?p+":"+line:String.valueOf(id);Object ts=config.timestampField().isBlank()?null:f.get(config.timestampField());long t=ts instanceof Number n?n.longValue():System.currentTimeMillis();Map<String,String>h=new HashMap<>();h.put("source","hdfs-file");h.put("path",p.toString());h.put("line",String.valueOf(line));h.put("format",config.fileFormatType().name());return new DataEntity(sid,t,f,h);}private Map<String,Object>parts(Path p){Map<String,Object>m=new LinkedHashMap<>();String v=p.toString().replace('\\','/');int n=v.lastIndexOf('/');if(n>0)for(String s:v.substring(0,n).split("/")){int i=s.indexOf('=');if(i>0&&i<s.length()-1)m.put(s.substring(0,i),s.substring(i+1));}return m;}}
